sys_script_include.script:
var CycloidIntegration = Class.create();
CycloidIntegration.prototype = {
	initialize: function() {},

	_getConfig: function() {
		var APP_ID = 'x_1829062_cycloi_1';
		gs.info("Attempting to read configuration from " + APP_ID + "_cycloid_config...");

		var gr = new GlideRecord(APP_ID + '_cycloid_config');
		gs.info("Table exists: " + gr.isValid());

		gr.query();
		gs.info("Query executed. Number of records found: " + gr.getRowCount());

		if (gr.next()) {
			var config = {
				api_url: gr.getValue('api_url'),
				org: gr.getValue('organization_canonical'),
				catalog_category: gr.getValue('catalog_category'), // REQUIRED: sc_category sys_id or title
				console_url: gr.getValue('console_url'),
				api_key: gr.getValue('api_key')
			};
			gs.info("Configuration values: " + JSON.stringify(config));
			return config;
		} else {
			gs.error("No records found in " + APP_ID + "_cycloid_config.");
			return null;
		}
	},

	getStacks: function() {
		var config = this._getConfig();
		if (!config) return [];

		if (!config.api_url || !config.org || !config.api_key) {
			gs.error("Incomplete configuration: api_url=" + config.api_url + ", org=" + config.org + ", apiKey=" + !!config.api_key);
			return [];
		}

		var endpoint = config.api_url + '/organizations/' + encodeURIComponent(config.org) + '/service_catalogs?infra_import_stack%5Beq%5D=false&page_index=1&page_size=10000';
		gs.info("Calling Cycloid API at: " + endpoint);

		var rm = new sn_ws.RESTMessageV2();
		rm.setHttpMethod('get');
		rm.setEndpoint(endpoint);
		rm.setRequestHeader('Accept', 'application/json');
		rm.setRequestHeader('Authorization', 'Bearer ' + config.api_key);

		var response = rm.execute();
		var status = response.getStatusCode();
		var body = response.getBody();

		gs.info("API response status: " + status);

		if (status < 200 || status >= 300) {
			gs.error('Cycloid API Error (' + status + '): ' + body);
			return [];
		}

		try {
			var json = JSON.parse(body);
			gs.info("API response parsed successfully.");
			return json.data || json.items || json.stacks || json || [];
		} catch (e) {
			gs.error("JSON parsing error: " + e);
			return [];
		}
	},

	// Main entry called by Scheduled Script
	syncStacks: function() {
		gs.info('Starting stack synchronization with Cycloid API.');
		var config = this._getConfig();
		if (!config) return;

		// Resolve REQUIRED target category (must already exist)
		var categorySysId = this._resolveExistingCategory(config.catalog_category);
		if (!categorySysId) {
			gs.error("Configured 'catalog_category' not found. Provide an existing sc_category sys_id (preferred) or title.");
			return;
		}
		gs.info("Using service catalog category: " + categorySysId);

		var stacks = this.getStacks();
		if (stacks.length === 0) {
			gs.info('No stacks were retrieved.');
			return;
		}
		gs.info('Successfully retrieved ' + stacks.length + ' stacks.');

		var APP_ID = 'x_1829062_cycloi_1';
		var TABLE_NAME = APP_ID + '_cycloid_stack';

		for (var i = 0; i < stacks.length; i++) {
			var stack = stacks[i];

			// Build external URL to open when user clicks the tile/card
			var stackUrl = (config.console_url || '').replace(/\/+$/,'') +
				'/organizations/' + encodeURIComponent(config.org) +
				'/stacks/' + encodeURIComponent(stack.ref);

			var grItem = new GlideRecord(TABLE_NAME);
			grItem.addQuery('u_cycloid_stack_ref', stack.ref);
			grItem.query();

			var isUpdate = grItem.next();
			if (!isUpdate) grItem.initialize();

			// REQUIRED catalog item fields for external redirect + portal cards
			grItem.name = stack.name;
			grItem.short_description = (stack.description || 'Cycloid Service Catalog Stack').toString().substring(0, 160);
			grItem.description = stack.description || 'Cycloid Service Catalog Stack';
			grItem.category = categorySysId;

			// Make it a Content item that opens an external URL
			grItem.type = 'content';               // important: content item
			grItem.content_type = 'external';      // external link
			grItem.url = stackUrl;                 // where to go
			grItem.url_target = '_blank';          // open in new tab (or use '_self')

			grItem.active = true;
			grItem.sys_class_name = TABLE_NAME;
			grItem.setValue('u_cycloid_stack_ref', stack.ref);

			var itemSysId = isUpdate ? grItem.update() : grItem.insert();
			if (!itemSysId) {
				gs.error("Failed to " + (isUpdate ? "update" : "create") + " item for stack: " + stack.name);
				continue;
			}

			// Try to set the picture if an image URL is provided
			if (stack.image) {
				this._applyImageFromUrl(TABLE_NAME, itemSysId, stack.image);
			}

			gs.info((isUpdate ? "Updated" : "Created") + " item for stack '" + stack.name + "' (" + itemSysId + ")");
		}
	},

	// Resolve an existing sc_category by sys_id (preferred) or by title.
	_resolveExistingCategory: function(input) {
		var v = (input || '').toString().trim();
		if (!v) return null;

		if (this._isValidSysId(v)) {
			var byId = new GlideRecord('sc_category');
			if (!byId.isValid()) return null;
			byId.addQuery('sys_id', v);
			byId.query();
			if (byId.next()) return byId.getUniqueValue();
		}

		var byTitle = new GlideRecord('sc_category');
		if (!byTitle.isValid()) return null;
		byTitle.addQuery('title', v);
		byTitle.query();
		if (byTitle.next()) return byTitle.getUniqueValue();

		return null;
	},

	// Download an image URL and set it as the item's picture (and thumbnail)
	_applyImageFromUrl: function(tableName, itemSysId, imageUrl) {
		try {
			if (!/^https?:\/\//i.test(imageUrl)) {
				gs.warn("Invalid image URL: " + imageUrl);
				return;
			}

			var rm = new sn_ws.RESTMessageV2();
			rm.setHttpMethod('get');
			rm.setEndpoint(imageUrl);
			rm.setRequestHeader('Accept', 'image/*');
			var resp = rm.execute();
			var status = resp.getStatusCode();
			if (status !== 200) {
				gs.warn("Image download failed (" + status + "): " + imageUrl);
				return;
			}

			var contentType = (resp.getHeader('Content-Type') || '').split(';')[0] || this._guessContentType(imageUrl);
			var bytes = resp.getBody(); // works for image write

			var item = new GlideRecord(tableName);
			if (!item.get(itemSysId)) {
				gs.warn("Item not found for image set: " + itemSysId);
				return;
			}

			// remove previous picture attachments (optional)
			try {
				var att = new GlideRecord('sys_attachment');
				att.addQuery('table_name', tableName);
				att.addQuery('table_sys_id', itemSysId);
				att.query();
				while (att.next()) {
					att.deleteRecord();
				}
			} catch (delErr) {}

			var gsa = new GlideSysAttachment();
			var fileName = this._fileNameFromUrl(imageUrl) || ('cycloid_icon.' + this._extFromType(contentType));
			var attachId = gsa.write(item, fileName, contentType, bytes);

			if (attachId) {
				item.setValue('picture', attachId);
				if (item.isValidField('thumbnail_image')) item.setValue('thumbnail_image', attachId);
				item.update();
			}
		} catch (e) {
			gs.warn("Failed to set image from URL: " + e);
		}
	},

	_guessContentType: function(url) {
		var ext = (url.split('?')[0].match(/\.([a-z0-9]+)$/i) || [,''])[1].toLowerCase();
		if (ext === 'png') return 'image/png';
		if (ext === 'jpg' || ext === 'jpeg') return 'image/jpeg';
		if (ext === 'gif') return 'image/gif';
		if (ext === 'svg') return 'image/svg+xml';
		return 'image/png';
	},

	_extFromType: function(ct) {
		if (ct === 'image/png') return 'png';
		if (ct === 'image/jpeg') return 'jpg';
		if (ct === 'image/gif') return 'gif';
		if (ct === 'image/svg+xml') return 'svg';
		return 'png';
	},

	_fileNameFromUrl: function(url) {
		try {
			var clean = url.split('?')[0];
			var name = clean.substring(clean.lastIndexOf('/') + 1);
			return name || null;
		} catch (e) {
			return null;
		}
	},

	_isValidSysId: function(v) {
		return /^[0-9a-f]{32}$/.test(String(v || ''));
	},

	type: 'CycloidIntegration'
};
